'use strict';
(function(root){
function evaluate(v){
 const bounds={depth:[0,1e15],duplicate:[0,100],withdrawal:[0,100],order:[0,1e15],inventory:[0,1e15],limit:[1,1e15],age:[0,1e9],maxAge:[1,1e9],cash:[0,1e15],margin:[0,1e15],outflows:[0,1e15]};
 for(const [k,[lo,hi]] of Object.entries(bounds))if(!Number.isFinite(v[k])||v[k]<lo||v[k]>hi)throw Error('Invalid '+k+' input.');
 const effectiveDepth=v.depth*(1-v.duplicate/100)*(1-v.withdrawal/100),fundingGap=Math.max(0,v.margin+v.outflows-v.cash);
 const checks=[['Quote freshness',v.age>v.maxAge,'Pause new orders using this feed; reconcile sequence gaps and compare independent prices before resuming.'],['Executable depth',v.order>effectiveDepth,'Reduce the proposed slice and validate firm liquidity; displayed depth may disappear before arrival.'],['Inventory capacity',v.inventory+v.order>v.limit,'Reserve outstanding orders across venues before admitting additional exposure; reconcile fills and cancel acknowledgements.'],['Funding coverage',fundingGap>0,'Escalate to treasury; confirm eligible collateral and committed funding before increasing exposure.']].map(([name,breach,action])=>({name,breach,action}));
 return {effectiveDepth,fundingGap,inventoryAfter:v.inventory+v.order,status:checks.some(c=>c.breach)?'HOLD FOR REVIEW':'WITHIN ENTERED LIMITS',checks};
}
root.SystemicControls={evaluate};if(typeof module!=='undefined')module.exports=root.SystemicControls;
if(typeof document==='undefined')return;
const fields=[['depth','Displayed depth (USD)',1000000],['duplicate','Assumed duplicate depth (%)',30],['withdrawal','Additional withdrawal (%)',50],['order','Proposed order (USD)',400000],['inventory','Current + reserved exposure (USD)',600000],['limit','Inventory limit (USD)',900000],['age','Quote age (ms)',150],['maxAge','Maximum quote age (ms)',100],['cash','Available cash / eligible collateral (USD)',300000],['margin','Stressed margin call (USD)',350000],['outflows','Other due outflows (USD)',50000]];
const policies=[
 ['Duplicate orders and ghost liquidity','Measure post-fill cancellations and deduplicate related depth. Reserve parent-order exposure across venues; cancellations release capacity only after acknowledgement.'],
 ['Latency arbitrage and adverse selection','Monitor quote age, feed sequence gaps, arrival slippage and post-fill markouts. Reject stale references; benchmark routing on executable outcomes.'],
 ['Inventory spirals and hot-potato volume','Aggregate positions and outstanding commitments across venues. Limit new exposure and participation; distinguish repeated turnover from replenishing depth.'],
 ['Crowding and liquidity commonality','Stress simultaneous withdrawal across assets and counterparties. Review common signals and correlated exits; validate portfolio liquidity using stressed volume.'],
 ['Margin tightening and fat tails','Combine price shocks, haircuts and margin calls. Maintain a tested funding plan; use historical and reverse stress scenarios alongside distribution-based models.'],
 ['Routing overload and settlement failures','Test burst traffic, reconnects, duplicate messages and late fills. Use idempotent order IDs, bounded queues, reconciliation and rehearsed failover.'],
 ['Regulatory lag and correlated cutoffs','Predefine escalation and restart criteria. Replay interacting strategies and venue outages; test kill controls and consequences of simultaneous withdrawal.'],
 ['Incentives and real-economy impact','Have the board review deferred compensation, leverage limits and long-horizon capital allocation. Map derivatives and counterparty incentives; software cannot resolve these governance choices.']
];
const panel=document.createElement('section');panel.id='systemic';panel.className='view';panel.innerHTML=`<div class="section-head"><div><h2>Systemic risk controls</h2><p>Assess a proposed order against liquidity, inventory and funding constraints.</p></div><span class="badge">Scenario analysis</span></div><p class="public-note">Inputs below are illustrative assumptions until you replace them with verified observations. These checks do not send or cancel orders. Thresholds require institution-specific approval.</p><form id="controlForm" class="card"><div class="control-fields">${fields.map(([k,label,val])=>`<label>${label}<input class="text-input" name="${k}" type="number" step="any" min="${['limit','maxAge'].includes(k)?1:0}" ${['duplicate','withdrawal'].includes(k)?'max="100"':''} value="${val}" required></label>`).join('')}</div><div class="controls"><button class="btn primary">Evaluate controls</button><button class="btn" type="button" id="controlExport" disabled>Download assessment</button></div></form><div id="controlResult" aria-live="polite"></div><article class="card" style="margin-top:16px"><h2>Response playbooks</h2><div class="grid-even">${policies.map(([title,body])=>`<div><h3>${title}</h3><p>${body}</p></div>`).join('')}</div><p class="notice">Proposed operational responses, not a guarantee of market stability or a compliance determination. Live detection requires synchronized order-level feeds and broker integration.</p><p><a href="https://www.sec.gov/files/faq-15c-5-risk-management-controls-bd.htm" target="_blank" rel="noopener">SEC market-access controls</a> · <a href="https://www.esma.europa.eu/sites/default/files/2026-02/ESMA74-1505669079-10311_Supervisory_Briefing_on_Algorithmic_Trading_in_the_EU.pdf" target="_blank" rel="noopener">ESMA algorithmic trading supervision</a> · <a href="https://www.bis.org/committees/bcbs/basel-consolidated-guidelines/module/lqy/10" target="_blank" rel="noopener">BIS liquidity stress guidance</a></p></article>`;
document.querySelector('main').append(panel);
const nav=document.createElement('button');nav.textContent='Systemic risk controls';nav.dataset.view='systemic';nav.onclick=()=>show('systemic');document.querySelector('.nav').prepend(nav);
let snapshot=null;
document.getElementById('controlForm').oninput=()=>{snapshot=null;document.getElementById('controlExport').disabled=true;document.getElementById('controlResult').textContent='Inputs changed. Evaluate controls to update results.';};
document.getElementById('controlForm').onsubmit=e=>{e.preventDefault();try{const inputs=Object.fromEntries(fields.map(([k])=>[k,Number(e.target.elements[k].value)])),result=evaluate(inputs);snapshot={generatedAt:new Date().toISOString(),model:'Scenario controls v1',inputType:'User-entered assumptions; not live market telemetry',inputs,result};document.getElementById('controlResult').innerHTML=`<article class="card" style="margin-top:16px"><h2 class="${result.checks.some(c=>c.breach)?'warn':'up'}">${result.status}</h2><p>Stressed executable depth: ${fmt(result.effectiveDepth)} · Funding shortfall: ${fmt(result.fundingGap)} · Exposure after order: ${fmt(result.inventoryAfter)}</p>${result.checks.map(c=>`<div class="risk-row"><b>${c.name}: ${c.breach?'BREACH':'Within entered limit'}</b><p>${c.breach?c.action:'Continue monitoring; this check alone does not authorize trading.'}</p></div>`).join('')}<p class="notice">Depth = displayed × (1 − duplicate fraction) × (1 − additional withdrawal). Exposure assumes the order increases absolute exposure. Funding gap = max(0, margin + other outflows − available resources). No price-impact forecast is calculated.</p></article>`;document.getElementById('controlExport').disabled=false;logActivity('Systemic controls evaluated',snapshot);}catch(err){document.getElementById('controlResult').textContent=err.message;}};
document.getElementById('controlExport').onclick=()=>{if(snapshot)download('riskpulse-controls.json',JSON.stringify(snapshot,null,2),'application/json');};
})(typeof globalThis!=='undefined'?globalThis:this);
